CREATE TABLE `bia_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `visit_id` int(11) NOT NULL,
  `age` int(11) DEFAULT NULL,
  `sex` enum('MALE','FEMALE','OTHER','PREFER_NOT_TO_SAY') DEFAULT NULL,
  `waist_circumference_cm` decimal(5,2) DEFAULT NULL,
  `waist_status` tinyint(1) DEFAULT NULL COMMENT 'wc_risk: 0=ปกติ, 1=เสี่ยง',
  `weight_kg` decimal(5,2) DEFAULT NULL,
  `height_cm` decimal(5,2) DEFAULT NULL,
  `bmi` decimal(5,2) DEFAULT NULL,
  `bmi_category` varchar(50) DEFAULT NULL,
  `fat_mass_kg` decimal(5,2) DEFAULT NULL,
  `body_fat_percentage` decimal(5,2) DEFAULT NULL,
  `pbf_cat` tinyint(1) DEFAULT NULL COMMENT 'pbf_cat: 1=น้อย, 2=ปกติ, 3=มาก',
  `visceral_fat_kg` decimal(5,2) DEFAULT NULL,
  `visceral_fat_level` decimal(5,2) DEFAULT NULL COMMENT 'vfat_level: ตัวเลข level จากเครื่อง BIA',
  `visceral_fat_cat` tinyint(1) DEFAULT NULL COMMENT 'vfat_cat: 1=น้อย, 2=ปกติ, 3=มาก',
  `muscle_mass_kg` decimal(5,2) DEFAULT NULL,
  `muscle_mass_cat` tinyint(1) DEFAULT NULL COMMENT 'muscle_cat: 1=น้อย, 2=ปกติ, 3=มาก',
  `bone_mass_kg` decimal(5,2) DEFAULT NULL,
  `bone_mass_cat` tinyint(1) DEFAULT NULL COMMENT 'bone_cat: 1=น้อย, 2=ปกติ, 3=มาก',
  `water_percentage` decimal(5,2) DEFAULT NULL,
  `water_status` tinyint(1) DEFAULT NULL COMMENT 'water_status: 0=เพียงพอ, 1=ขาดน้ำ',
  `metabolic_rate` int(11) DEFAULT NULL,
  `hip_circumference_cm` decimal(5,2) DEFAULT NULL,
  `waist_hip_ratio` decimal(4,3) DEFAULT NULL,
  `weight_management` varchar(50) DEFAULT NULL,
  `food_recommendation` varchar(100) DEFAULT NULL,
  `measured_by` int(11) DEFAULT NULL,
  `staff_signature` varchar(255) DEFAULT NULL,
  `measurement_date` date DEFAULT NULL,
  `notes` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `mac_cm` decimal(5,2) DEFAULT NULL,
  `cc_cm` decimal(5,2) DEFAULT NULL,
  `source_staff_id` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_bia_visit` (`visit_id`),
  KEY `measured_by` (`measured_by`),
  KEY `ix_bia_records_id` (`id`),
  KEY `ix_bia_records_created_at` (`created_at`),
  KEY `ix_bia_records_visit_id` (`visit_id`),
  CONSTRAINT `bia_records_ibfk_1` FOREIGN KEY (`visit_id`) REFERENCES `visits` (`id`) ON DELETE CASCADE,
  CONSTRAINT `bia_records_ibfk_2` FOREIGN KEY (`measured_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=409 DEFAULT CHARSET=utf8;
