--
-- Table structure for table `visits`
--

DROP TABLE IF EXISTS `visits`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `visits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `respondent_id` int(11) NOT NULL,
  `visit_number` int(11) NOT NULL,
  `visit_date` date DEFAULT NULL,
  `visit_time` time DEFAULT NULL,
  `facility_id` int(11) DEFAULT NULL,
  `visit_type` enum('BASELINE','FOLLOW_UP','FINAL') DEFAULT NULL,
  `notes` text,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `is_deleted` tinyint(1) DEFAULT NULL,
  `source_assessment_id` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_respondent_visit` (`respondent_id`,`visit_number`),
  KEY `facility_id` (`facility_id`),
  KEY `created_by` (`created_by`),
  KEY `ix_visits_visit_date` (`visit_date`),
  KEY `ix_visits_id` (`id`),
  KEY `ix_visits_respondent_id` (`respondent_id`),
  KEY `ix_visits_source_assessment_id` (`source_assessment_id`),
  CONSTRAINT `visits_ibfk_1` FOREIGN KEY (`respondent_id`) REFERENCES `respondents` (`id`),
  CONSTRAINT `visits_ibfk_2` FOREIGN KEY (`facility_id`) REFERENCES `facilities` (`id`),
  CONSTRAINT `visits_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=444 DEFAULT CHARSET=utf8;
/*!40101 SET character_set_client = @saved_cs_client */;

